package com.tripmateai.mapper; import com.tripmateai.dto.response.journal.*; import com.tripmateai.entity.*; import java.util.*; public final class JournalMapper {private JournalMapper(){} public static JournalEntryResponse summary(TravelJournal j){return new JournalEntryResponse(j.getId(),j.getJournalDate(),j.getTitle());} public static JournalEntryDetailResponse detail(TravelJournal j,List<JournalPhoto> p){return new JournalEntryDetailResponse(j.getId(),j.getJournalDate(),j.getTitle(),j.getContent(),p.stream().map(x->new JournalPhotoResponse(x.getId(),x.getImageUrl(),x.getCaption(),x.getSortOrder())).toList());}}
